// Resize the existing webviews; never recreate partitions, navigate or change individual zoom.
const squareGridObserver=new ResizeObserver(()=>{
 const grid=$('gameGrid');if(!grid)return;
 const layout=grid.classList.contains('layout-grid')?'grid':grid.classList.contains('layout-duo')?'duo':'focus';
 grid.style.setProperty('--tile-size',window.GridiumProfessional.squareTileSize(grid.clientWidth,grid.clientHeight,layout)+'px');
});squareGridObserver.observe($('gameGrid'));
new MutationObserver(()=>squareGridObserver.unobserve($('gameGrid'))||squareGridObserver.observe($('gameGrid'))).observe($('gameGrid'),{attributes:true,attributeFilter:['class']});
